mapper.select:
SELECT * FROM ( SELECT c.cr_year, c.cr_fuel_type, c.cr_trans, ct.ct_key, ct.ct_name, ct.ct_type, c.cr_thumbnail, c.cr_price, ROW_NUMBER() OVER ( PARTITION BY ct.ct_key ORDER BY c.cr_price ASC ) AS rn FROM car c JOIN rental r ON c.cr_re_num = r.re_num JOIN region reg ON r.re_rg_num = reg.rg_num JOIN car_type ct ON c.cr_ct_key = ct.ct_key
AND reg.rg_name = #{cri.rg_name}
AND ct.ct_type IN
#{type}
AND ct.ct_name LIKE CONCAT('%', #{cri.ct_name}, '%')
AND c.cr_fuel_type IN
#{fuel}
AND c.cr_trans IN
#{gear}
AND c.cr_price <= #{cri.price}
) temp WHERE temp.rn = 1
ORDER BY cr_price ASC
ORDER BY cr_year DESC
ORDER BY ct_key DESC
